package main
import("bytes";"encoding/binary";"fmt";"math";"testing";"time";"github.com/yangl1996/riblt")
func TestCount(t *testing.T){values:=[]int64{math.MinInt64,math.MaxInt64,-8193,-8192,-65,-64,-1,0,1,63,64,8191,8192};for _,x:=range values{b:=encodeCount(nil,x,0,0);y,l,e:=decodeCount(b,0,0);if e!=nil||l!=len(b)||y!=x{t.Fatal(x,y,l,e)};var tmp [10]byte;expected:=binary.PutVarint(tmp[:],x);if expected!=len(b){t.Fatal("boundary",x)}};for i:=0;i<10000;i++{n:=uint64(10000000);expect:=expectation(n,i);for _,delta:=range []int64{-8192,-64,-1,0,1,63,64,8192}{c:=expect+delta;b:=encodeCount(nil,c,n,i);x,_,e:=decodeCount(b,n,i);if x!=c||e!=nil{t.Fatal(i,c,x)}}};if _,_,e:=decodeCount([]byte{128},0,0);e==nil{t.Fatal("malformed accepted")}}
func TestHeaderFrame(t *testing.T){key0=123;key1=456;for _,n:=range []uint64{0,1,127,128,1000000,10000000}{h:=header(n);got,e:=parseHeader(h);if got!=n||e!=nil{t.Fatal(n,e)};for _,delta:=range []int64{-10000,-65,-1,0,1,64,10000}{for _,i:=range []int{0,1,9999}{c:=riblt.CodedSymbol[item]{HashedSymbol:riblt.HashedSymbol[item]{Symbol:item((1<<30)-1),Hash:math.MaxUint64},Count:expectation(n,i)+delta};b:=frame(nil,c,n,i);out,_,e:=unframe(b,n,i);if e!=nil||out!=c{t.Fatal(c,out,e)};bad:=append([]byte(nil),b...);bad[3]|=128;if _,_,e=unframe(bad,n,i);e==nil{t.Fatal("padding accepted")}}}}}
func TestIncremental(t *testing.T){key0=123;key1=456;for _,d:=range []dataset{{D:0,A:[]item{1,2},B:[]item{1,2}},{D:2,A:[]item{1,2,3},B:[]item{1},AO:[]item{2,3}},{D:2,A:[]item{1},B:[]item{1,2,3},BO:[]item{2,3}},{D:6,A:[]item{1,2,3,4},B:[]item{1,5,6,7},AO:[]item{2,3,4},BO:[]item{5,6,7}}}{r:=measure(d,2,10000,time.Minute);for _,x:=range r{if x.Status!="success"||!x.Truth||!x.Accounting||!x.CountIdentical||x.Symbols<1{t.Fatal(fmt.Sprintf("%+v",x))}};if r[0].WireSHA!=r[1].WireSHA||r[0].Symbols!=r[1].Symbols{t.Fatal("repeatability")};if d.D>1&&len(r[0].Checkpoints)==0{t.Fatal("missing incomplete prefixes")}}}
func TestOfficialHash(t *testing.T){key0=123;key1=456;if item(1).Hash()>>49==0{t.Fatal("unexpected mask")};var e riblt.Encoder[item];for _,v:=range []item{1,2,3}{e.AddSymbol(v)};first:=e.ProduceNextCodedSymbol();if first.Count!=3||first.Hash!=item(1).Hash()^item(2).Hash()^item(3).Hash(){t.Fatal(first)};if !bytes.Equal(header(100),header(100)){t.Fatal("metadata deterministic")}}
